CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE IF NOT EXISTS travelmind_users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text UNIQUE NOT NULL,password_hash text NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_destinations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,district text,state text,country text NOT NULL DEFAULT 'India',latitude double precision NOT NULL,longitude double precision NOT NULL,bounding_box jsonb,source text NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(name,state,country));
CREATE TABLE IF NOT EXISTS travelmind_places(id text PRIMARY KEY,destination_id uuid REFERENCES travelmind_destinations(id),name text NOT NULL,description text,latitude double precision NOT NULL,longitude double precision NOT NULL,category text NOT NULL,tags text[] DEFAULT '{}',average_cost integer,rating numeric,visit_duration_minutes integer DEFAULT 60,indoor_outdoor text,importance_score numeric,image_url text,image_attribution text,source text NOT NULL,raw_data jsonb,active boolean DEFAULT true,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_place_cache(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),destination_id uuid REFERENCES travelmind_destinations(id),query_hash text NOT NULL UNIQUE,payload jsonb NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_trips(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES travelmind_users(id),destination_id uuid REFERENCES travelmind_destinations(id),destination text,budget integer,currency text DEFAULT 'INR',duration_days integer,travellers integer,status text DEFAULT 'planned',requirements jsonb,weather jsonb,route jsonb,started_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_trip_preferences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES travelmind_trips(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('INTEREST','HARD_AVOID','SOFT_AVOID')),original_value text NOT NULL,normalized_values text[] DEFAULT '{}',weight numeric DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_trip_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES travelmind_trips(id) ON DELETE CASCADE,place_id text REFERENCES travelmind_places(id),position integer,start_time timestamptz,end_time timestamptz,cost integer,status text DEFAULT 'planned',priority_type text DEFAULT 'AI_RECOMMENDED',priority_score integer DEFAULT 50,recommendation_score integer,metadata jsonb,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_custom_places(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES travelmind_trips(id) ON DELETE CASCADE,name text NOT NULL,display_name text,latitude double precision NOT NULL,longitude double precision NOT NULL,user_priority text DEFAULT 'USER_MUST_VISIT',source text DEFAULT 'NOMINATIM',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_trip_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES travelmind_trips(id) ON DELETE CASCADE,event_type text NOT NULL,data jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_trip_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES travelmind_trips(id) ON DELETE CASCADE,revision_number integer,items jsonb,changes jsonb,explanation text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_recommendation_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES travelmind_trips(id),place_id text REFERENCES travelmind_places(id),scores jsonb,final_score numeric,reasons jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_knowledge_entities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,name text NOT NULL UNIQUE,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travelmind_knowledge_relationships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_entity_id uuid REFERENCES travelmind_knowledge_entities(id),relationship_type text NOT NULL,target_entity_id uuid REFERENCES travelmind_knowledge_entities(id),weight numeric DEFAULT 1,created_at timestamptz DEFAULT now());
